package com.osintworkbench.mobile;
import android.content.Context; import android.os.Build; import android.os.Handler; import android.os.Looper; import org.json.JSONObject; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.text.SimpleDateFormat; import java.util.*; import java.util.concurrent.*;
final class Diagnostics {
 private static final String BRIDGE="http://127.0.0.1:8765"; private static final ExecutorService IO=Executors.newSingleThreadExecutor(); private static Context app; private static Thread.UncaughtExceptionHandler previous;
 private static File queue(){return new File(app.getFilesDir(),"diagnostic-outbox.jsonl");}
 static void install(Context c){app=c.getApplicationContext();previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((t,e)->{record("uncaught_exception",e,"thread="+t.getName());try{flushNow();}catch(Exception ignored){}if(previous!=null)previous.uncaughtException(t,e);});flush();}
 static void record(String kind,Throwable error,String context){if(app==null)return;try{JSONObject j=new JSONObject();j.put("event",kind);j.put("time",new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ",Locale.US).format(new Date()));j.put("app_version","0.2.0");j.put("android",Build.VERSION.RELEASE);j.put("sdk",Build.VERSION.SDK_INT);j.put("device",Build.MANUFACTURER+" "+Build.MODEL);j.put("context",context==null?"":context);j.put("error_type",error==null?"Diagnostic":error.getClass().getName());j.put("message",error==null?"":String.valueOf(error.getMessage()));StringWriter sw=new StringWriter();if(error!=null)error.printStackTrace(new PrintWriter(sw));j.put("stack",sw.toString());synchronized(Diagnostics.class){try(FileOutputStream o=new FileOutputStream(queue(),true)){o.write((j.toString()+"\n").getBytes(StandardCharsets.UTF_8));}}if(!"uncaught_exception".equals(kind))flush();}catch(Exception ignored){}}
 static void flush(){if(app!=null)IO.execute(()->{try{flushNow();}catch(Exception ignored){}});}
 private static void flushNow()throws Exception{File f=queue();if(!f.exists()||f.length()==0)return;List<String> lines=new ArrayList<>();synchronized(Diagnostics.class){try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),StandardCharsets.UTF_8))){String s;while((s=r.readLine())!=null)if(!s.trim().isEmpty())lines.add(s);}}List<String> failed=new ArrayList<>();for(String line:lines){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(BRIDGE+"/report").openConnection();c.setConnectTimeout(1200);c.setReadTimeout(1800);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.getOutputStream().write(line.getBytes(StandardCharsets.UTF_8));int status=c.getResponseCode();if(status<200||status>=300)failed.add(line);}catch(Exception ex){failed.add(line);}finally{if(c!=null)c.disconnect();}}synchronized(Diagnostics.class){try(FileOutputStream o=new FileOutputStream(f,false)){for(String s:failed)o.write((s+"\n").getBytes(StandardCharsets.UTF_8));}}}
 static void fetchIssues(Callback cb){IO.execute(()->{String result;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(BRIDGE+"/issues").openConnection();c.setConnectTimeout(1500);c.setReadTimeout(2500);try(InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))>0)o.write(b,0,n);result=new String(o.toByteArray(),StandardCharsets.UTF_8);}}catch(Exception e){result="Мост Termux недоступен. Запустите bridge.py в Termux и повторите.\n"+e.getClass().getSimpleName();}finally{if(c!=null)c.disconnect();}String v=result;new Handler(Looper.getMainLooper()).post(()->cb.done(v));});}
 interface Callback{void done(String value);}
}